#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

static int k_global;

int64 dist_in_block(int64 ra, int64 rb, int k) {
    // assumes ra >= rb
    if (ra == rb) return 0;
    int n = (int)(ra - rb + 1);
    vector<int64> g(n, 0); // g[i] corresponds to value rb + i
    // g[0] = 0 for rb
    for (int64 s = rb + 1; s <= ra; ++s) {
        int idx = (int)(s - rb);
        int64 best = g[idx - 1]; // move: s -> s-1
        for (int x = 2; x <= k; ++x) {
            int64 t = s - (s % x);
            if (t >= rb) best = min(best, g[(int)(t - rb)]);
        }
        g[idx] = 1 + best;
    }
    return g[n - 1];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b;
    int k;
    if (!(cin >> a >> b >> k)) return 0;

    // Compute L = lcm(2..k)
    int64 L = 1;
    for (int x = 2; x <= k; ++x) {
        int64 g = std::gcd(L, (int64)x);
        L = (L / g) * x;
    }

    int64 qa = a / L, ra = a % L;
    int64 qb = b / L, rb = b % L;

    if (qa == qb) {
        cout << dist_in_block(ra, rb, k) << "\n";
        return 0;
