        int64 S_full = dist_in_block(L - 1, 0, k);
        int64 S_final = dist_in_block(L - 1, rb, k);
        int64 blocks_between = qa - qb - 1; // number of full intermediate blocks
        __int128 total = 0;
        total += S_top;
        total += 1; // cross from top block to next
        if (blocks_between > 0) total += (__int128)blocks_between * (S_full + 1);
        total += S_final;
        long long ans = (long long)total;
        cout << ans << "\n";
        return 0;
    }
}
